SELECT A.GBN AS GBN, A.DONG_ID AS DONG_ID, B.DONG_NAME AS DONG_NAME, A.HO_ID AS HO_ID, A.LINE_NO AS LINE_NO, A.LINE_GBN AS LINE_GBN, NULL AS MINWON_AREAR_SEQ, NULL AS AREAR_NAME, COUNT(A.SLIP_NO) AS TOTAL_CNT, SUM(CASE WHEN A.STATUS_CD = '1' THEN 1 ELSE 0 END) AS PROC_CNT, SUM(CASE WHEN A.STATUS_CD = '2' THEN 1 ELSE 0 END) AS HOLD_CNT, SUM(CASE WHEN A.STATUS_CD = '3' THEN 1 ELSE 0 END) AS REJECT_CNT, SUM(CASE WHEN A.STATUS_CD = '4' OR A.STATUS_CD = '' OR A.STATUS_CD IS NULL THEN 1 ELSE 0 END) AS PENDING_CNT FROM dbo.TMN_MINWON A LEFT JOIN dbo.TMN_DONG B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.DONG_ID = B.DONG_ID WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND A.GBN = '1' AND (A.DEL_YN = '' OR ISNULL(A.DEL_YN,'N') != 'Y')
AND A.MINWON_DATE >= #{START_DATE}
AND A.MINWON_DATE <= #{END_DATE}
GROUP BY A.GBN, A.DONG_ID, B.DONG_NAME, A.HO_ID, A.LINE_NO, A.LINE_GBN ORDER BY CONVERT(INT, A.DONG_ID), A.LINE_GBN

SELECT A.GBN AS GBN, A.DONG_ID AS DONG_ID, '동외공용' AS DONG_NAME, NULL AS HO_ID, NULL AS LINE_NO, NULL AS LINE_GBN, A.MINWON_AREAR_SEQ AS MINWON_AREAR_SEQ, B.AREAR_NAME AS AREAR_NAME, COUNT(A.SLIP_NO) AS TOTAL_CNT, SUM(CASE WHEN A.STATUS_CD = '1' THEN 1 ELSE 0 END) AS PROC_CNT, SUM(CASE WHEN A.STATUS_CD = '2' THEN 1 ELSE 0 END) AS HOLD_CNT, SUM(CASE WHEN A.STATUS_CD = '3' THEN 1 ELSE 0 END) AS REJECT_CNT, SUM(CASE WHEN A.STATUS_CD = '4' OR A.STATUS_CD = '' OR A.STATUS_CD IS NULL THEN 1 ELSE 0 END) AS PENDING_CNT FROM dbo.TMN_MINWON A LEFT JOIN dbo.TMN_MINWON_AREAR B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.MINWON_AREAR_SEQ = B.MINWON_AREAR_SEQ WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND A.GBN NOT IN ('0', '1') AND (A.DEL_YN = '' OR ISNULL(A.DEL_YN,'N') != 'Y')
AND A.MINWON_DATE >= #{START_DATE}
AND A.MINWON_DATE <= #{END_DATE}
GROUP BY A.GBN, A.DONG_ID, A.MINWON_AREAR_SEQ, B.AREAR_NAME ORDER BY CONVERT(INT, A.MINWON_AREAR_SEQ)

SELECT * FROM ( SELECT A.GBN AS GBN, A.DONG_ID AS DONG_ID, B.DONG_NAME AS DONG_NAME, A.HO_ID AS HO_ID, A.LINE_NO AS LINE_NO, A.LINE_GBN AS LINE_GBN, NULL AS MINWON_AREAR_SEQ, NULL AS AREAR_NAME, COUNT(A.SLIP_NO) AS TOTAL_CNT, SUM(CASE WHEN A.STATUS_CD = '1' THEN 1 ELSE 0 END) AS PROC_CNT, SUM(CASE WHEN A.STATUS_CD = '2' THEN 1 ELSE 0 END) AS HOLD_CNT, SUM(CASE WHEN A.STATUS_CD = '3' THEN 1 ELSE 0 END) AS REJECT_CNT, SUM(CASE WHEN A.STATUS_CD = '4' OR A.STATUS_CD = '' OR A.STATUS_CD IS NULL THEN 1 ELSE 0 END) AS PENDING_CNT FROM dbo.TMN_MINWON A LEFT JOIN dbo.TMN_DONG B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.DONG_ID = B.DONG_ID WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND A.GBN = '1' AND (A.DEL_YN = '' OR ISNULL(A.DEL_YN,'N') != 'Y')
AND A.MINWON_DATE >= #{START_DATE}
AND A.MINWON_DATE <= #{END_DATE}
GROUP BY A.GBN, A.DONG_ID, B.DONG_NAME, A.HO_ID, A.LINE_NO, A.LINE_GBN UNION ALL SELECT A.GBN AS GBN, A.DONG_ID AS DONG_ID, '동외공용' AS DONG_NAME, NULL AS HO_ID, NULL AS LINE_NO, NULL AS LINE_GBN, A.MINWON_AREAR_SEQ AS MINWON_AREAR_SEQ, B.AREAR_NAME AS AREAR_NAME, COUNT(A.SLIP_NO) AS TOTAL_CNT, SUM(CASE WHEN A.STATUS_CD = '1' THEN 1 ELSE 0 END) AS PROC_CNT, SUM(CASE WHEN A.STATUS_CD = '2' THEN 1 ELSE 0 END) AS HOLD_CNT, SUM(CASE WHEN A.STATUS_CD = '3' THEN 1 ELSE 0 END) AS REJECT_CNT, SUM(CASE WHEN A.STATUS_CD = '4' OR A.STATUS_CD = '' OR A.STATUS_CD IS NULL THEN 1 ELSE 0 END) AS PENDING_CNT FROM dbo.TMN_MINWON A LEFT JOIN dbo.TMN_MINWON_AREAR B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.MINWON_AREAR_SEQ = B.MINWON_AREAR_SEQ WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND A.GBN NOT IN ('0', '1') AND (A.DEL_YN = '' OR ISNULL(A.DEL_YN,'N') != 'Y')
AND A.MINWON_DATE >= #{START_DATE}
AND A.MINWON_DATE <= #{END_DATE}
GROUP BY A.GBN, A.DONG_ID, A.MINWON_AREAR_SEQ, B.AREAR_NAME) T ORDER BY CONVERT(INT, T.DONG_ID), ISNULL(T.LINE_GBN, '999999'), ISNULL(T.MINWON_AREAR_SEQ, '0')

