SELECT A.OFFICE_CODE AS OFFICE_CODE, A.SLIP_NO AS SLIP_NO, A.MINWON_DATE AS MINWON_DATE, A.MINWON_GBN AS MINWON_GBN, '[' + ISNULL(C.GBN_NAME, ' ') + ']' + CHAR(13) + CHAR(10) + ISNULL(A.DESCR, '') AS DESCR, A.STATUS_CD AS STATUS_CD, CASE WHEN A.STATUS_CD = '1' THEN '처리' WHEN A.STATUS_CD = '2' THEN '보류' WHEN A.STATUS_CD = '3' THEN '반려' WHEN A.STATUS_CD = '4' THEN '처리중' ELSE '미결' END AS STATUS_NAME, A.GBN AS GBN, A.DONG_ID AS DONG_ID, A.HO_ID AS HO_ID, A.LINE_NO AS LINE_NO, A.LINE_GBN AS LINE_GBN, A.MINWON_AREAR_SEQ AS MINWON_AREAR_SEQ, B.AREAR_NAME AS AREAR_NAME, A.RECEIPT_USER AS RECEIPT_USER, D.WORK_USER AS WORK_USER FROM dbo.TMN_MINWON A LEFT JOIN dbo.TMN_MINWON_AREAR B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.MINWON_AREAR_SEQ = B.MINWON_AREAR_SEQ LEFT JOIN TMN_MINWON_GBN C ON A.OFFICE_CODE = C.OFFICE_CODE AND A.MINWON_GBN = C.GBN_ID LEFT JOIN TMN_MINWON_WORK D ON A.OFFICE_CODE = D.OFFICE_CODE AND A.SLIP_NO = D.SLIP_NO AND A.MINWON_DATE = D.MINWON_DATE AND (D.DEL_YN = '' OR ISNULL(D.DEL_YN,'N') != 'Y') WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND A.DEL_YN = 'Y'
