SELECT SUBSTRING(A.MINWON_DATE, 1,6) AS MONTH, COUNT(A.SLIP_NO) AS TOTAL_CNT, SUM(CASE WHEN A.STATUS_CD = '1' THEN 1 ELSE 0 END) AS PROC_CNT, SUM(CASE WHEN A.STATUS_CD = '2' THEN 1 ELSE 0 END) AS HOLD_CNT, SUM(CASE WHEN A.STATUS_CD = '3' THEN 1 ELSE 0 END) AS REJECT_CNT, SUM(CASE WHEN A.STATUS_CD = '4' THEN 1 ELSE 0 END) AS ING_CNT, SUM(CASE WHEN A.STATUS_CD = '' OR A.STATUS_CD IS NULL THEN 1 ELSE 0 END) AS RPENDING_CNT FROM dbo.TMN_MINWON A WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND ISNULL(A.DEL_YN, 'N') != 'Y'
AND SUBSTRING(A.MINWON_DATE, 1,6) >= #{START_MONTH}
AND SUBSTRING(A.MINWON_DATE, 1,6) <= #{END_MONTH}
GROUP BY SUBSTRING(A.MINWON_DATE, 1,6)

SELECT A.WORK_USER AS WORK_USER, COUNT(A.WORK_SEQ) AS TOTAL_CNT, SUM(CASE WHEN B.STATUS_CD = '1' THEN 1 ELSE 0 END) AS PROC_CNT, SUM(CASE WHEN B.STATUS_CD = '2' THEN 1 ELSE 0 END) AS HOLD_CNT, SUM(CASE WHEN B.STATUS_CD = '3' THEN 1 ELSE 0 END) AS REJECT_CNT, SUM(CASE WHEN B.STATUS_CD = '4' THEN 1 ELSE 0 END) AS ING_CNT, SUM(CASE WHEN B.STATUS_CD = '' OR B.STATUS_CD IS NULL THEN 1 ELSE 0 END) AS RPENDING_CNT FROM dbo.TMN_MINWON_WORK A INNER JOIN dbo.TMN_MINWON B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.SLIP_NO = B.SLIP_NO AND A.MINWON_DATE = B.MINWON_DATE WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND ISNULL(A.DEL_YN, 'N') != 'Y' AND ISNULL(B.DEL_YN, 'N') != 'Y'
AND A.MINWON_DATE >= #{START_DATE}
AND A.MINWON_DATE <= #{END_DATE}
GROUP BY A.WORK_USER

SELECT CASE WHEN A.GBN = '0' THEN '세대' WHEN A.GBN = '1' AND A.LINE_GBN = '109002' THEN '계단' WHEN A.GBN = '1' AND A.LINE_GBN = '109003' THEN '현관' WHEN A.GBN = '1' AND A.LINE_GBN = '109997' THEN '엘리베이터' WHEN A.GBN = '1' AND A.LINE_GBN = '109998' THEN '루프탑' ELSE B.AREAR_NAME END AS PLACE, COUNT(A.SLIP_NO) AS TOTAL_CNT, SUM(CASE WHEN A.STATUS_CD = '1' THEN 1 ELSE 0 END) AS PROC_CNT, SUM(CASE WHEN A.STATUS_CD = '2' THEN 1 ELSE 0 END) AS HOLD_CNT, SUM(CASE WHEN A.STATUS_CD = '3' THEN 1 ELSE 0 END) AS REJECT_CNT, SUM(CASE WHEN A.STATUS_CD = '4' THEN 1 ELSE 0 END) AS ING_CNT, SUM(CASE WHEN A.STATUS_CD = '' OR A.STATUS_CD IS NULL THEN 1 ELSE 0 END) AS RPENDING_CNT FROM dbo.TMN_MINWON A LEFT JOIN dbo.TMN_MINWON_AREAR B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.MINWON_AREAR_SEQ = B.MINWON_AREAR_SEQ WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND ISNULL(A.DEL_YN, 'N') != 'Y'
AND A.MINWON_DATE >= #{START_DATE}
AND A.MINWON_DATE <= #{END_DATE}
GROUP BY CASE WHEN A.GBN = '0' THEN '세대' WHEN A.GBN = '1' AND A.LINE_GBN = '109002' THEN '계단' WHEN A.GBN = '1' AND A.LINE_GBN = '109003' THEN '현관' WHEN A.GBN = '1' AND A.LINE_GBN = '109997' THEN '엘리베이터' WHEN A.GBN = '1' AND A.LINE_GBN = '109998' THEN '루프탑' ELSE B.AREAR_NAME END

SELECT A.DONG_ID AS DONG_ID, B.DONG_NAME AS DONG_NAME, COUNT(A.SLIP_NO) AS TOTAL_CNT, SUM(CASE WHEN A.STATUS_CD = '1' THEN 1 ELSE 0 END) AS PROC_CNT, SUM(CASE WHEN A.STATUS_CD = '2' THEN 1 ELSE 0 END) AS HOLD_CNT, SUM(CASE WHEN A.STATUS_CD = '3' THEN 1 ELSE 0 END) AS REJECT_CNT, SUM(CASE WHEN A.STATUS_CD = '4' THEN 1 ELSE 0 END) AS ING_CNT, SUM(CASE WHEN A.STATUS_CD = '' OR A.STATUS_CD IS NULL THEN 1 ELSE 0 END) AS RPENDING_CNT FROM dbo.TMN_MINWON A LEFT JOIN dbo.TMN_DONG B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.DONG_ID = B.DONG_ID WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND ISNULL(A.DEL_YN, 'N') != 'Y'
AND A.MINWON_DATE >= #{START_DATE}
AND A.MINWON_DATE <= #{END_DATE}
GROUP BY A.DONG_ID, B.DONG_NAME

SELECT A.MINWON_GBN AS MINWON_GBN, B.GBN_NAME AS GBN_NAME, COUNT(A.SLIP_NO) AS TOTAL_CNT, SUM(CASE WHEN A.STATUS_CD = '1' THEN 1 ELSE 0 END) AS PROC_CNT, SUM(CASE WHEN A.STATUS_CD = '2' THEN 1 ELSE 0 END) AS HOLD_CNT, SUM(CASE WHEN A.STATUS_CD = '3' THEN 1 ELSE 0 END) AS REJECT_CNT, SUM(CASE WHEN A.STATUS_CD = '4' THEN 1 ELSE 0 END) AS ING_CNT, SUM(CASE WHEN A.STATUS_CD = '' OR A.STATUS_CD IS NULL THEN 1 ELSE 0 END) AS RPENDING_CNT FROM dbo.TMN_MINWON A LEFT JOIN dbo.TMN_MINWON_GBN B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.MINWON_GBN = B.GBN_ID WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND ISNULL(A.DEL_YN, 'N') != 'Y'
AND A.MINWON_DATE >= #{START_DATE}
AND A.MINWON_DATE <= #{END_DATE}
GROUP BY A.MINWON_GBN, B.GBN_NAME
